at.resources WHERE dynamicType(attrs.`c`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE (coalesce(attrs.`c`.:Int64 = 3, false) OR coalesce(attrs.`c`.:Float64 = 3, false))), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`c`), arrayExists(x -> x = 3, events.attrs.`c`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`c`), arrayExists(x -> x = 3, links.attrs.`c`.:Int64), multiIf(dynamicType(scope_attrs.`c`) != 'None', (coalesce(scope_attrs.`c`.:Int64 = 3, false) OR coalesce(scope_attrs.`c`.:Float64 = 3, false)), false))))))))) ORDER BY span FORMAT TSV
